// --- Safety Guardrails for Thumbnail and Sandbox ---
if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }


// --- Global Variables for Uncler M Variants ---
var uM_colors = ["#ff5e62", "#ff9966", "#ffe066", "#2c3e50", "#3498db"];
var speedMult = 2.5;
var lineScale = 1.3;
var dynamicShift = 0;
var scalePulse = 1.0;
var rotAngle = 0;
var gridOffset = 0;
var uM_rot = 0;

// === Inspired by 'Day4243RainyDays' by 'trumpliu' ===
// Created as variant #1 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
// p5.js – 雨景（极简冷色、俯视、微距感）
// 画布 9:16 自适应，冷色配色，撞击溅射如烟花，同心椭圆涟漪

// 雨点下落：重力加速度、初速度范围（越大落得越快）、水平漂移幅度
const GRAVITY = 0.9;
const RAIN_SPEED_MIN = 25;
const RAIN_SPEED_MAX = 40;
const RAIN_TILT = 0.05;
const SPAWN_RATE = 10.0;      // 每帧生成雨点的概率系数，越大雨越密
const DROP_LEN = 250;         // 雨滴视觉长度（像素）
const DESIGN_H = 1920;       // 设计稿参考高度，用于响应式缩放

// 涟漪：数量（每撞击产生的同心圆层数）、透明度（0–255）、椭圆形扁平度（0–1，越小越扁）
const RIPPLE_RING_MIN = 1;
const RIPPLE_RING_MAX = 3;
const RIPPLE_ALPHA_MAX = 255; // 刚出现时的透明度（0–255）
const RIPPLE_ALPHA_MIN = 200;     // 扩散到最大半径时的透明度；0=完全淡出，越大淡出越轻
const RIPPLE_ELLIPSE_RATIO = 0.6;

// 底部留白：地面线距画布底边的距离，保证雨滴与涟漪不超出画布
const BOTTOM_MARGIN = 200;
// 撞击点垂直随机范围（像素），让落点不在一条直线上
const IMPACT_Y_VARIATION = 55;

// 冷色配色：纯白、冰蓝、青色（无暖色）
const COLORS = {
  white: [255, 255, 255],
  ice: [176, 224, 255],
  //cyan: [0, 229, 255],
};

// 全局数组与画布状态
let drops = [];      // 当前雨滴
let splashes = [];   // 溅射粒子
let ripples = [];    // 涟漪
let groundY = 0;     // 地面 y 坐标（触地判定线）
let scale = 1;       // 相对设计稿的缩放比例

function setup() {
  resizeCanvasToWindow();
  colorMode(RGB, 255);
  noFill();
}

// 按窗口尺寸创建画布（高度为窗口 80%，宽高比 9:16）
function resizeCanvasToWindow() {
  let canvasHeight = (typeof windowHeight !== "undefined" && windowHeight > 0)
    ? windowHeight * 0.9
    : 720;
  let canvasWidth = (1080 / 1920) * canvasHeight;
  createCanvas(canvasWidth, canvasHeight);
  scale = height / DESIGN_H;
  groundY = height - max(BOTTOM_MARGIN, 40 * scale);
}

// 窗口尺寸变化时重算画布并清空粒子
function windowResized() {
  var canvasHeight = (typeof windowHeight !== "undefined" && windowHeight > 0)
    ? windowHeight * 0.8
    : 720;
  var canvasWidth = (1080 / 1920) * canvasHeight;
  resizeCanvas(canvasWidth, canvasHeight);
  scale = height / DESIGN_H;
  groundY = height - max(BOTTOM_MARGIN, 40 * scale);
  drops = [];
  splashes = [];
  ripples = [];
}

function draw() {
  // === Variant 1: Neon Kinetic Glitch Modification ===
  dynamicShift = sin((frameCount * speedMult) * 0.08) * 40;

  background(10, 10, 15);

  // 按概率生成新雨滴
  if (random(1) < SPAWN_RATE * 0.016) {
    drops.push(new Raindrop());
  }

  // 更新并绘制雨滴；触地则移除并生成溅射与涟漪
  for (let i = drops.length - 1; i >= 0; i--) {
    drops[i].update();
    drops[i].show();
    if (drops[i].y >= groundY) {
      let x = drops[i].x;
      let impactY = groundY + random(-IMPACT_Y_VARIATION, IMPACT_Y_VARIATION);
      drops.splice(i, 1);
      spawnSplash(x, impactY);
      spawnRipples(x, impactY);
    }
  }

  // 更新并绘制溅射粒子（烟花式短促火花，无长尾）
  for (let i = splashes.length - 1; i >= 0; i--) {
    splashes[i].update();
    splashes[i].show();
    if (splashes[i].life <= 0) splashes.splice(i, 1);
  }

  // 更新并绘制涟漪，过期则移除
  for (let i = ripples.length - 1; i >= 0; i--) {
    ripples[i].update();
    ripples[i].show();
    if (ripples[i].dead) ripples.splice(i, 1);
  }
}

// 在撞击点生成溅射粒子：随机方向、速度与冷色
function spawnSplash(x, y) {
  const count = floor(random(6, 20));
  const palette = [COLORS.white, COLORS.ice];
  for (let i = 0; i < count; i++) {
    const angle = random(TWO_PI);
    const speed = random(4, 14) * scale;
    const c = random(palette);
    splashes.push(new Splash(x, y, angle, speed, c));
  }
}

// 涟漪：撞击点产生多层同心椭圆，随时间扩散并淡出
function spawnRipples(x, y) {
  const ringCount = floor(random(RIPPLE_RING_MIN, RIPPLE_RING_MAX));
  const baseMaxR = max(45 * scale, 28);
  const ringSpacing = max(1.8 * scale, 4);
  for (let i = 0; i < ringCount; i++) {
    ripples.push(new Ripple(x, y, i * 0.06, baseMaxR + i * ringSpacing));
  }
}

// ——— 雨滴 ———
class Raindrop {
  constructor() {
    this.x = random(0, width);
    this.y = random(-80 * scale, 0);   // 从画布上方随机高度出现
    this.vy = random(RAIN_SPEED_MIN, RAIN_SPEED_MAX) * scale;
    this.vx = (random(1) - 0.5) * RAIN_TILT * this.vy;  // 微小水平漂移
    this.len = random(DROP_LEN * 0.6, DROP_LEN) * scale;
    this.alpha = random(180, 255);
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
    this.vy += GRAVITY * 0.1 * scale;  // 重力加速
  }

  show() {
    // 用线段表示雨滴：尾端到尖端
    const tipX = this.x + this.vx * 2;
    const tipY = this.y + this.vy * 2;
    const tailX = this.x - this.vx * 2 - (this.len / (DROP_LEN * scale)) * 8 * scale;
    const tailY = this.y - this.vy * 2 - this.len;
    stroke(200, 235, 255, this.alpha);
    strokeWeight(1.2 * scale);
    line(tailX, tailY, tipX, tipY);
  }
}

// ——— 溅射粒子：放射状爆发、高空气阻力快速减速、短火花无长尾 ———
class Splash {
  constructor(x, y, angle, speed, color) {
    this.x = x;
    this.y = y;
    this.vx = cos(angle) * speed;
    this.vy = sin(angle) * speed;
    this.color = color;
    this.life = 1;                      // 生命值，用于淡出
    this.decay = random(0.018, 0.032);  // 每帧衰减
    this.airResist = 0.92;              // 空气阻力，快速减速
    this.prevX = x;
    this.prevY = y;
  }

  update() {
    this.prevX = this.x;
    this.prevY = this.y;
    this.x += this.vx;
    this.y += this.vy;
    this.vx *= this.airResist;
    this.vy *= this.airResist;
    this.life -= this.decay;
  }

  show() {
    if (this.life <= 0) return;
    // 沿运动方向画短线段（两头尖中间亮，模拟运动模糊）
    const dx = this.x - this.prevX;
    const dy = this.y - this.prevY;
    const len = sqrt(dx * dx + dy * dy) || 1;
    const ux = dx / len;
    const uy = dy / len;
    const sparkLen = min(12 * scale, len * 2);
    const midX = this.x - ux * sparkLen * 0.5;
    const midY = this.y - uy * sparkLen * 0.5;
    const x0 = midX - ux * sparkLen * 0.5;
    const y0 = midY - uy * sparkLen * 0.5;
    const x1 = midX + ux * sparkLen * 0.5;
    const y1 = midY + uy * sparkLen * 0.5;

    const a = 255 * this.life;
    stroke(this.color[0], this.color[1], this.color[2], a);
    strokeWeight(2.8 * scale);
    strokeCap(ROUND);
    drawingContext.shadowBlur = 14 * scale;  // 光晕
    drawingContext.shadowColor = `rgb(${this.color[0]},${this.color[1]},${this.color[2]})`;
    line(x0, y0, x1, y1);
    drawingContext.shadowBlur = 0;
    strokeWeight(1.2 * scale);
    stroke(this.color[0], this.color[1], this.color[2], a * 0.5);
    line(x0, y0, x1, y1);
  }
}

// ——— 涟漪：多层同心椭圆，随时间扩散并淡出 ———
class Ripple {
  constructor(x, y, delay, maxRadius) {
    this.x = x;
    this.y = y;
    this.delay = delay;       // 延迟启动，形成依次扩散
    this.radius = 0;
    this.maxRadius = maxRadius;
    this.speed = max((2.2 + random(0.8)) * scale, 0.7);
    this.alpha = RIPPLE_ALPHA_MAX;
    this.dead = false;
    this.started = false;
  }

  update() {
    if (this.delay > 0) {
      this.delay -= 0.016;
      return;
    }
    if (!this.started) this.started = true;
    this.radius += this.speed;
    const progress = this.radius / this.maxRadius;
    const t = (1 - progress) * (1 - progress);
    this.alpha = RIPPLE_ALPHA_MIN + (RIPPLE_ALPHA_MAX - RIPPLE_ALPHA_MIN) * t;
    if (this.radius >= this.maxRadius || this.alpha <= 0) this.dead = true;
  }

  show() {
    if (this.delay > 0 || this.alpha <= 0) return;
    stroke(200, 245, 255, this.alpha);
    strokeWeight(max(1.2 * scale, 0.9));
    const w = this.radius * 2;
    const h = w * RIPPLE_ELLIPSE_RATIO;  // 椭圆扁率
    ellipse(this.x, this.y, w, h);
  }
}
